class FakeFD:
    def __init__(self):
        self.params = {
            'test': False,
            'fragment_retries': 0,
            'skip_unavailable_fragments': True,
        }
        self.downloaded_urls = []
        self.contents = []
        self.finished = False

    def _prepare_and_start_frag_download(self, ctx):
        ctx['fragment_index'] = 0

    def _download_fragment(self, ctx, fragment_url, info_dict):
        self.downloaded_urls.append(fragment_url)
        return True, ('content:' + fragment_url).encode('utf-8')

    def _append_fragment(self, ctx, frag_content):
        self.contents.append(frag_content)

    def _finish_frag_download(self, ctx):
        self.finished = True

downloader = FakeFD()
result = DashSegmentsFD.real_download(
    downloader,
    'video.mp4',
    {
        'fragment_base_url': 'https://example.com/media/',
        'fragments': [
            {'url': 'https://cdn.example.com/init.mp4'},
            {'path': 'segment-1.m4s'},
        ],
    })

assert result is True
assert downloader.downloaded_urls == [
    'https://cdn.example.com/init.mp4',
    'https://example.com/media/segment-1.m4s',
]
assert downloader.contents == [
    b'content:https://cdn.example.com/init.mp4',
    b'content:https://example.com/media/segment-1.m4s',
]
assert downloader.finished is True

